<?php
namespace RealEstatePro\Admin;defined('ABSPATH')||exit;
final class Settings{public function register():void{add_action('admin_menu',function(){add_menu_page('RealEstate Pro Suite','RealEstate Pro','manage_re_pro_suite','re-pro-suite',[$this,'page'],'dashicons-building',26);});add_action('admin_init',function(){register_setting('re_pro_suite','re_pro_ai_provider',['sanitize_callback'=>fn($v)=>in_array($v,['openai','anthropic'],true)?$v:'openai']);register_setting('re_pro_suite','re_pro_openai_key',['sanitize_callback'=>'sanitize_text_field']);register_setting('re_pro_suite','re_pro_anthropic_key',['sanitize_callback'=>'sanitize_text_field']);});}public function page():void{?><div class="wrap"><h1>RealEstate Pro Suite</h1><form method="post" action="options.php"><?php settings_fields('re_pro_suite');?><table class="form-table"><tr><th>AI Provider</th><td><select name="re_pro_ai_provider"><option value="openai">OpenAI</option><option value="anthropic">Anthropic</option></select></td></tr><tr><th>OpenAI API Key</th><td><input class="regular-text" type="password" name="re_pro_openai_key" value="<?php echo esc_attr(get_option('re_pro_openai_key',''));?>"></td></tr><tr><th>Anthropic API Key</th><td><input class="regular-text" type="password" name="re_pro_anthropic_key" value="<?php echo esc_attr(get_option('re_pro_anthropic_key',''));?>"></td></tr></table><?php submit_button();?></form></div><?php}}